import{_ as n,a0 as s,w as d,s as p,ao as l,I as o,x as t,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 Fedora 上使用 GIMP 轻松编辑图像 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 上使用 GIMP 轻松编辑图像 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 上使用 GIMP 轻松编辑图像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 上使用 GIMP 轻松编辑图像 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191113 Edit images on Fedora easily with GIMP","title":"在 Fedora 上使用 GIMP 轻松编辑图像","tag":"201912","desc":""},"relativePath":"201912/20191113 Edit images on Fedora easily with GIMP.md","filePath":"[post].md"}'),g={name:"201912/20191113 Edit images on Fedora easily with GIMP.md"};function m(u,a,h,b,f,y){const r=s("Link");return d(),p("div",null,[a[15]||(a[15]=l('<h1 id="在-fedora-上使用-gimp-轻松编辑图像" tabindex="-1">在 Fedora 上使用 GIMP 轻松编辑图像 <a class="header-anchor" href="#在-fedora-上使用-gimp-轻松编辑图像" aria-label="Permalink to “在 Fedora 上使用 GIMP 轻松编辑图像”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/gimp-magazine-816x346.jpg" alt=""></p><p>GIMP（GNU Image Manipulation Program 的缩写）是自由开源的图像处理软件。它有很多的功能，从简单的图像编辑，到复杂的滤镜、脚本，甚至是动画，它是流行的商业同类软件的一款很好的替代品。</p><p>继续阅读来学习如何在 Fedora 上安装和使用 GIMP。这篇文章涉及基本的日常图像编辑工作。</p><h3 id="安装-gimp" tabindex="-1">安装 GIMP <a class="header-anchor" href="#安装-gimp" aria-label="Permalink to “安装 GIMP”">​</a></h3><p>GIMP 在官方 Fedora 存储库中可获得。为安装它，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gimp</span></span></code></pre></div><h3 id="单窗口模式" tabindex="-1">单窗口模式 <a class="header-anchor" href="#单窗口模式" aria-label="Permalink to “单窗口模式”">​</a></h3><p>在你打开应用程序后，它显示带有工具箱和主编辑区的暗色主题窗口。注意，它有两种窗口模式，你可以通过选择“<ruby>窗口<rt>Windows</rt></ruby> -&gt; <ruby>单窗口模式<rt>Single Window Mode</rt></ruby>”在其中切换。通过选中这个选项，用户界面的所有组件将显示在单个窗口中。否则，它们将是分离的。</p><h3 id="加载图像" tabindex="-1">加载图像 <a class="header-anchor" href="#加载图像" aria-label="Permalink to “加载图像”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-00-44-300x165.png" alt=""></p><p>为加载图像，转到“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>打开<rt>Open</rt></ruby>”，然后选择你的文件并选择你的图像文件。</p><h3 id="重新调整一个图像的大小" tabindex="-1">重新调整一个图像的大小 <a class="header-anchor" href="#重新调整一个图像的大小" aria-label="Permalink to “重新调整一个图像的大小”">​</a></h3><p>为重新调整图像大小，你可以基于一对参数重新调整大小，包括像素和百分比 —— 在编辑图像时，这两个参数很方便。</p><p>让我们假使我们需要缩小 Fedora 30 背景图像到它当前大小的 75%。为此，选择“<ruby>图像<rt> Image</rt></ruby> -&gt; <ruby>比例<rt>Scale</rt></ruby>”，然后在比例对话框上，在单位下拉列表中选择“<ruby>百分比<rt>percentage</rt></ruby>”。接下来，输入 “75” 作为宽度或高度，然后按 Tab 键。默认情况下，其它尺寸将自动地调整大小，以相应地与更改的尺寸保持纵横比。现在，保存其它选项不变，并按比例。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-17-33-300x262.png" alt=""></p><p>该图像缩小到其原始尺寸的 75%。</p><h3 id="旋转图像" tabindex="-1">旋转图像 <a class="header-anchor" href="#旋转图像" aria-label="Permalink to “旋转图像”">​</a></h3><p>旋转是一种变换操作，因此，你可以从主菜单下的“<ruby>图像<rt>Image</rt></ruby> -&gt; <ruby>变换<rt>Transform</rt></ruby>”下找到它，其中有图像旋转 90° 或 180° 的选项。在上述选项下也有垂直或水平翻转图像的选项。</p><p>让我们假使我们需要旋转图像 90°。在应用一次 90° 顺时针旋转和水平翻转后，我们的图像将看起来像这样：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-41-28-300x243.png" alt="Transforming an image with GIMP"></p><h3 id="添加文本" tabindex="-1">添加文本 <a class="header-anchor" href="#添加文本" aria-label="Permalink to “添加文本”">​</a></h3><p>添加文本非常简单。只需要从工具箱中选择 “A” 图标，然后，在你的图像上，单击你想要添加文本的位置。如果工具箱不可见，从“<ruby>窗口<rt>Windows</rt></ruby> -&gt; <ruby>新建工具箱<rt>New Toolbox</rt></ruby>”打开它。</p><p>当你编辑文本时，你可能注意到，文本对话框有字体自定义选项，包括字体系列、字体大小等等。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-47-54-300x237.png" alt="Adding text to image in GIMP"></p><h3 id="保存和导出" tabindex="-1">保存和导出 <a class="header-anchor" href="#保存和导出" aria-label="Permalink to “保存和导出”">​</a></h3><p>你可以从“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>保存<rt>Save</rt></ruby>”或通过按 <code>Ctrl+S</code> 来将你的编辑保存为一个带有 <code>.xcf</code> 扩展名的 GIMP 工程。或者，你可以导出你的图像，例如，以 PNG 或 JPEG 格式。为导出图像，转到“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>导出为<rt>Export As</rt></ruby>”或按 <code>Ctrl+Shift+E</code>，接下来，在你面前将产生一个你可以选择输出图像和名称的对话框。</p><hr>',28)),o("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"https://fedoramagazine.org/edit-images-on-fedora-easily-with-gimp/"},{default:i(()=>[...a[0]||(a[0]=[t("https://fedoramagazine.org/edit-images-on-fedora-easily-with-gimp/",-1)])]),_:1})]),o("p",null,[a[6]||(a[6]=t("作者：",-1)),e(r,{href:"https://fedoramagazine.org/author/powergame/"},{default:i(()=>[...a[2]||(a[2]=[t("Mehdi Haghgoo",-1)])]),_:1}),a[7]||(a[7]=t(" 选题：",-1)),e(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[t("lujun9972",-1)])]),_:1}),a[8]||(a[8]=t(" 译者：",-1)),e(r,{href:"https://github.com/robsean"},{default:i(()=>[...a[4]||(a[4]=[t("robsean",-1)])]),_:1}),a[9]||(a[9]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[a[12]||(a[12]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[t("LCTT",-1)])]),_:1}),a[13]||(a[13]=t(" 原创编译，",-1)),e(r,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[t("Linux中国",-1)])]),_:1}),a[14]||(a[14]=t(" 荣誉推出",-1))])])}const M=n(g,[["render",m]]);export{T as __pageData,M as default};
